    errors,
  );
  if (obj.version !== "restaurant-arena-action/v1") errors.push(`${path}.version: expected restaurant-arena-action/v1`);
  if (!isArenaId(obj.episodeId)) errors.push(`${path}.episodeId: expected arena id`);
  if (!isArenaId(obj.actorId)) errors.push(`${path}.actorId: expected arena id`);
  if (typeof obj.actorType !== "string" || !ACTOR_TYPES.has(obj.actorType)) errors.push(`${path}.actorType: invalid actor type`);
