  if (typeof obj.tool !== "string" || !TOOLS.has(obj.tool)) errors.push(`${path}.tool: invalid tool`);
  if (typeof obj.arguments !== "object" || obj.arguments === null || Array.isArray(obj.arguments)) {
    errors.push(`${path}.arguments: expected object`);
