  if (!isInteger(obj.tick) || obj.tick < 0) errors.push(`${path}.tick: expected integer >= 0`);
  if (!isDateTime(obj.timestamp)) errors.push(`${path}.timestamp: expected date-time`);
  if (!isArenaId(obj.requestId)) errors.push(`${path}.requestId: expected arena id`);
  if (typeof obj.idempotencyKey !== "string" || obj.idempotencyKey.length > 130 || !IDEMPOTENCY_PATTERN.test(obj.idempotencyKey)) {
