function validateReplayInput(input: unknown, path: string, errors: string[]): void {
  const obj = requireObject(input, path, errors);
  if (!obj) return;
  if (!isInteger(obj.tick) || obj.tick < 0) errors.push(`${path}.tick: expected integer >= 0`);
  if (!isSha256(obj.stateHash)) errors.push(`${path}.stateHash: expected sha256 hash`);
  if (obj.restaurantStateHash !== undefined && !isSha256(obj.restaurantStateHash)) {
    errors.push(`${path}.restaurantStateHash: expected sha256 hash`);
  }
  if (typeof obj.kind !== "string" || !INPUT_KINDS.has(obj.kind)) {
    errors.push(`${path}.kind: invalid replay input kind`);
    return;
  }
  if (obj.kind === "step") {
    recordUnknownKeys(obj, new Set(["kind", "tick", "stateHash", "restaurantStateHash", "action"]), path, errors);
    if (typeof obj.action !== "string" || obj.action.length < 1) errors.push(`${path}.action: expected non-empty string`);
  } else if (obj.kind === "time") {
    recordUnknownKeys(obj, new Set(["kind", "tick", "stateHash", "restaurantStateHash"]), path, errors);
  } else if (obj.kind === "envelope") {
    recordUnknownKeys(obj, new Set(["kind", "tick", "stateHash", "restaurantStateHash", "envelope", "telemetry"]), path, errors);
    if (obj.envelope === undefined) errors.push(`${path}.envelope: required`);
    else validateEnvelope(obj.envelope, `${path}.envelope`, errors);
    if (obj.telemetry !== undefined && (typeof obj.telemetry !== "object" || obj.telemetry === null || Array.isArray(obj.telemetry))) {
      errors.push(`${path}.telemetry: expected object`);
    }
  } else if (obj.kind === "controllers") {
    recordUnknownKeys(obj, new Set(["kind", "tick", "stateHash", "restaurantStateHash", "roles"]), path, errors);
    if (!Array.isArray(obj.roles)) {
      errors.push(`${path}.roles: expected array`);
    } else {
      const seen = new Set<string>();
      for (const [index, role] of obj.roles.entries()) {
        if (typeof role !== "string" || !TRACE_ROLES.has(role)) errors.push(`${path}.roles[${index}]: invalid role`);
        else if (seen.has(role)) errors.push(`${path}.roles: roles must be unique`);
        else seen.add(role);
      }
    }
  }
}

function validateDeletion(deletion: unknown, path: string, errors: string[]): void {
  const obj = requireObject(deletion, path, errors);
  if (!obj) return;
  recordUnknownKeys(obj, new Set(["requestId", "status"]), path, errors);
  if (obj.requestId !== null && !isArenaId(obj.requestId)) errors.push(`${path}.requestId: expected arena id or null`);
  if (typeof obj.status !== "string" || !DELETION_STATUSES.has(obj.status)) errors.push(`${path}.status: invalid deletion status`);
}

function validateTerminal(terminal: unknown, path: string, errors: string[]): void {
  const obj = requireObject(terminal, path, errors);
  if (!obj) return;
  recordUnknownKeys(obj, new Set(["status", "tick", "reason"]), path, errors);
  if (typeof obj.status !== "string" || !TERMINAL_STATUSES.has(obj.status)) errors.push(`${path}.status: invalid terminal status`);
  if (!isInteger(obj.tick) || obj.tick < 0) errors.push(`${path}.tick: expected integer >= 0`);
  if (obj.reason !== null && typeof obj.reason !== "string") errors.push(`${path}.reason: expected string or null`);
}

function validateReplay(replay: unknown, path: string, errors: string[]): void {
  const obj = requireObject(replay, path, errors);
  if (!obj) return;
  recordUnknownKeys(obj, new Set(["variation", "inputs", "finalStateHash", "finalRestaurantStateHash"]), path, errors);
  if (typeof obj.variation !== "string" || !VARIATIONS.has(obj.variation)) errors.push(`${path}.variation: invalid variation`);
  if (!Array.isArray(obj.inputs)) errors.push(`${path}.inputs: expected array`);
  else obj.inputs.forEach((input, index) => validateReplayInput(input, `${path}.inputs[${index}]`, errors));
  if (!isSha256(obj.finalStateHash)) errors.push(`${path}.finalStateHash: expected sha256 hash`);
  if (obj.finalRestaurantStateHash !== undefined && !isSha256(obj.finalRestaurantStateHash)) {
    errors.push(`${path}.finalRestaurantStateHash: expected sha256 hash`);
  }
}

function validateTable(table: unknown, path: string, errors: string[]): void {
  const obj = requireObject(table, path, errors);
  if (!obj) return;
  recordUnknownKeys(obj, new Set(["id", "seats", "status", "orderId"]), path, errors);
  if (!isArenaId(obj.id)) errors.push(`${path}.id: expected arena id`);
  if (!isInteger(obj.seats) || obj.seats < 1) errors.push(`${path}.seats: expected integer >= 1`);
  if (typeof obj.status !== "string" || !TABLE_STATUSES.has(obj.status)) errors.push(`${path}.status: invalid table status`);
  if (obj.orderId !== undefined && !isArenaId(obj.orderId)) errors.push(`${path}.orderId: expected arena id`);
}

function validateOrder(order: unknown, path: string, errors: string[]): void {
  const obj = requireObject(order, path, errors);
  if (!obj) return;
  recordUnknownKeys(obj, new Set(["id", "tableId", "items", "status", "allergy", "priority"]), path, errors);
  if (!isArenaId(obj.id)) errors.push(`${path}.id: expected arena id`);
  if (obj.tableId !== undefined && !isArenaId(obj.tableId)) errors.push(`${path}.tableId: expected arena id`);
  if (!Array.isArray(obj.items) || obj.items.some((item) => typeof item !== "string" || item.length < 1)) {
    errors.push(`${path}.items: expected array of non-empty strings`);
  }
  if (typeof obj.status !== "string" || !ORDER_STATUSES.has(obj.status)) errors.push(`${path}.status: invalid order status`);
  if (obj.allergy !== undefined && (typeof obj.allergy !== "string" || obj.allergy.length < 1)) {
    errors.push(`${path}.allergy: expected non-empty string`);
  }
  if (typeof obj.priority !== "string" || !PRIORITIES.has(obj.priority)) errors.push(`${path}.priority: invalid priority`);
}

function validateEquipment(item: unknown, path: string, errors: string[]): void {
  const obj = requireObject(item, path, errors);
  if (!obj) return;
  recordUnknownKeys(obj, new Set(["id", "kind", "status", "safetyThreshold", "reading"]), path, errors);
  if (!isArenaId(obj.id)) errors.push(`${path}.id: expected arena id`);
  if (typeof obj.kind !== "string" || !EQUIPMENT_KINDS.has(obj.kind)) errors.push(`${path}.kind: invalid equipment kind`);
  if (typeof obj.status !== "string" || !EQUIPMENT_STATUSES.has(obj.status)) errors.push(`${path}.status: invalid equipment status`);
  if (obj.safetyThreshold !== undefined && typeof obj.safetyThreshold !== "number") errors.push(`${path}.safetyThreshold: expected number`);
  if (obj.reading !== undefined && typeof obj.reading !== "number") errors.push(`${path}.reading: expected number`);
}

function validateWorker(worker: unknown, path: string, errors: string[]): void {
  const obj = requireObject(worker, path, errors);
  if (!obj) return;
  recordUnknownKeys(obj, new Set(["id", "role", "load", "location", "lastAction"]), path, errors);
  if (!isArenaId(obj.id)) errors.push(`${path}.id: expected arena id`);
  if (typeof obj.role !== "string" || !TRACE_ROLES.has(obj.role)) errors.push(`${path}.role: invalid role`);
  if (typeof obj.load !== "number" || obj.load < 0 || obj.load > 1) errors.push(`${path}.load: expected number in [0, 1]`);
  if (typeof obj.location !== "string" || !WORKER_LOCATIONS.has(obj.location)) errors.push(`${path}.location: invalid location`);
  if (obj.lastAction !== undefined && typeof obj.lastAction !== "string") errors.push(`${path}.lastAction: expected string`);
