function validateInitialState(state: unknown, path: string, errors: string[]): void {
  const obj = requireObject(state, path, errors);
  if (!obj) return;
  recordUnknownKeys(
    obj,
    new Set(["version", "seed", "episode", "clock", "tables", "orders", "inventory", "equipment", "workers", "emergency", "reputation", "outcomes"]),
    path,
    errors,
  );
  if (obj.version !== "restaurant-arena/v1") errors.push(`${path}.version: expected restaurant-arena/v1`);
  if (!isInteger(obj.seed) || obj.seed < 0) errors.push(`${path}.seed: expected integer >= 0`);

  const episode = requireObject(obj.episode, `${path}.episode`, errors);
  if (episode) {
    recordUnknownKeys(episode, new Set(["id", "phase", "tick", "maxTicks"]), `${path}.episode`, errors);
    if (!isArenaId(episode.id)) errors.push(`${path}.episode.id: expected arena id`);
    if (episode.phase !== "active" && episode.phase !== "complete") errors.push(`${path}.episode.phase: invalid phase`);
    if (!isInteger(episode.tick) || episode.tick < 0) errors.push(`${path}.episode.tick: expected integer >= 0`);
    if (!isInteger(episode.maxTicks) || episode.maxTicks < 1) errors.push(`${path}.episode.maxTicks: expected integer >= 1`);
  }

  const clock = requireObject(obj.clock, `${path}.clock`, errors);
  if (clock) {
    recordUnknownKeys(clock, new Set(["minute", "speed"]), `${path}.clock`, errors);
    if (!isInteger(clock.minute) || clock.minute < 0) errors.push(`${path}.clock.minute: expected integer >= 0`);
    if (!isInteger(clock.speed) || clock.speed < 1) errors.push(`${path}.clock.speed: expected integer >= 1`);
  }

  if (!Array.isArray(obj.tables)) errors.push(`${path}.tables: expected array`);
  else obj.tables.forEach((table, index) => validateTable(table, `${path}.tables[${index}]`, errors));

  if (!Array.isArray(obj.orders)) errors.push(`${path}.orders: expected array`);
  else obj.orders.forEach((order, index) => validateOrder(order, `${path}.orders[${index}]`, errors));

  const inventory = requireObject(obj.inventory, `${path}.inventory`, errors);
  if (inventory) {
    for (const [item, count] of Object.entries(inventory)) {
      if (!isInteger(count) || count < 0) errors.push(`${path}.inventory.${item}: expected integer >= 0`);
    }
  }

  if (!Array.isArray(obj.equipment)) errors.push(`${path}.equipment: expected array`);
  else obj.equipment.forEach((item, index) => validateEquipment(item, `${path}.equipment[${index}]`, errors));

  if (!Array.isArray(obj.workers)) errors.push(`${path}.workers: expected array`);
  else obj.workers.forEach((worker, index) => validateWorker(worker, `${path}.workers[${index}]`, errors));

  if (obj.emergency !== undefined) {
    const emergency = requireObject(obj.emergency, `${path}.emergency`, errors);
    if (emergency) {
      recordUnknownKeys(emergency, new Set(["kind", "active", "startedAt"]), `${path}.emergency`, errors);
      if (emergency.kind !== "oven_failure") errors.push(`${path}.emergency.kind: expected oven_failure`);
      if (typeof emergency.active !== "boolean") errors.push(`${path}.emergency.active: expected boolean`);
      if (!isInteger(emergency.startedAt) || emergency.startedAt < 0) errors.push(`${path}.emergency.startedAt: expected integer >= 0`);
    }
