    errors.push(`${path}.reputation: expected number in [0, 100]`);
  }

  const outcomes = requireObject(obj.outcomes, `${path}.outcomes`, errors);
  if (outcomes) {
    recordUnknownKeys(
      outcomes,
      new Set(["cash", "satisfaction", "waste", "waitTime", "completed", "safeOrders", "coordination", "correctionUptake"]),
      `${path}.outcomes`,
      errors,
    );
    if (typeof outcomes.cash !== "number" || outcomes.cash < 0) errors.push(`${path}.outcomes.cash: expected number >= 0`);
    if (typeof outcomes.satisfaction !== "number" || outcomes.satisfaction < 0 || outcomes.satisfaction > 1) {
      errors.push(`${path}.outcomes.satisfaction: expected number in [0, 1]`);
    }
    if (typeof outcomes.waste !== "number" || outcomes.waste < 0) errors.push(`${path}.outcomes.waste: expected number >= 0`);
    if (typeof outcomes.waitTime !== "number" || outcomes.waitTime < 0) errors.push(`${path}.outcomes.waitTime: expected number >= 0`);
    if (!isInteger(outcomes.completed) || outcomes.completed < 0) errors.push(`${path}.outcomes.completed: expected integer >= 0`);
    if (!isInteger(outcomes.safeOrders) || outcomes.safeOrders < 0) errors.push(`${path}.outcomes.safeOrders: expected integer >= 0`);
    if (typeof outcomes.coordination !== "number" || outcomes.coordination < 0 || outcomes.coordination > 1) {
      errors.push(`${path}.outcomes.coordination: expected number in [0, 1]`);
    }
    if (typeof outcomes.correctionUptake !== "number" || outcomes.correctionUptake < 0 || outcomes.correctionUptake > 1) {
      errors.push(`${path}.outcomes.correctionUptake: expected number in [0, 1]`);
    }
  }
}

/**
 * Field-by-field validator for restaurant-arena-trace-v3 records.
 * Returns every violation found rather than stopping at the first.
 */
export function validateArenaTraceV3(trace: unknown): TraceValidationResult {
  const errors: string[] = [];
  const obj = requireObject(trace, "$", errors);
  if (!obj) return { valid: false, errors };

  recordUnknownKeys(obj, TRACE_ROOT_KEYS, "$", errors);

  if (obj.version !== TRACE_V3_VERSION) errors.push(`$.version: expected ${TRACE_V3_VERSION}`);
  if (!isArenaId(obj.episodeId)) errors.push("$.episodeId: expected arena id");
  if (obj.sessionId !== undefined && !isArenaId(obj.sessionId)) errors.push("$.sessionId: expected arena id");
  if (!isInteger(obj.seed) || obj.seed < 0) errors.push("$.seed: expected integer >= 0");
  if (typeof obj.envVersion !== "string" || obj.envVersion.length < 1) errors.push("$.envVersion: expected non-empty string");
  if (obj.contractVersion !== TRACE_V3_CONTRACT_VERSION) errors.push(`$.contractVersion: expected ${TRACE_V3_CONTRACT_VERSION}`);
  if (typeof obj.runKind !== "string" || !RUN_KINDS.has(obj.runKind)) errors.push("$.runKind: expected live, synthetic, or benchmark");

  if (obj.initialState === undefined) errors.push("$.initialState: required");
  else validateInitialState(obj.initialState, "$.initialState", errors);

  if (!Array.isArray(obj.events)) errors.push("$.events: expected array");
  else obj.events.forEach((event, index) => validateEvent(event, `$.events[${index}]`, errors));

  if (obj.deletion === undefined) errors.push("$.deletion: required");
  else validateDeletion(obj.deletion, "$.deletion", errors);

  if (obj.replay === undefined) errors.push("$.replay: required");
  else validateReplay(obj.replay, "$.replay", errors);

  if (obj.terminal === undefined) errors.push("$.terminal: required");
  else validateTerminal(obj.terminal, "$.terminal", errors);

  return { valid: errors.length === 0, errors };
}

