const RUN_KINDS: ReadonlySet<string> = new Set(["live", "synthetic", "benchmark"]);
const DELETION_STATUSES: ReadonlySet<string> = new Set(["retained", "requested", "deleted"]);
const TERMINAL_STATUSES: ReadonlySet<string> = new Set(["active", "completed", "abandoned"]);
const VARIATIONS: ReadonlySet<string> = new Set(["tutorial-shift", "dinner-rush", "quiet-tuesday", "saturday-night"]);
const CORRECTION_CATEGORIES: ReadonlySet<string | null> = new Set(["safety", "priority", "quality", "pace", null]);
const SUBJECT_KINDS: ReadonlySet<string> = new Set(["order", "ingredient", "equipment", "handoff"]);
const INPUT_KINDS: ReadonlySet<string> = new Set(["step", "time", "envelope", "controllers"]);
const ORDER_STATUSES: ReadonlySet<string> = new Set(["queued", "seated", "preparing", "ready", "served", "cancelled"]);
const PRIORITIES: ReadonlySet<string> = new Set(["normal", "high"]);
const EQUIPMENT_KINDS: ReadonlySet<string> = new Set(["oven", "warming_shelf"]);
const EQUIPMENT_STATUSES: ReadonlySet<string> = new Set(["working", "failed", "degraded"]);
const TABLE_STATUSES: ReadonlySet<string> = new Set(["empty", "occupied"]);
const WORKER_LOCATIONS: ReadonlySet<string> = new Set(["floor", "kitchen", "pass", "queue"]);
