]);

function isInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value);
}

function isArenaId(value: unknown): value is string {
  return typeof value === "string" && value.length <= 64 && ARENA_ID_PATTERN.test(value);
}

function isSha256(value: unknown): value is string {
  return typeof value === "string" && SHA256_PATTERN.test(value);
}

function isDateTime(value: unknown): value is string {
  return typeof value === "string" && DATE_TIME_PATTERN.test(value) && !Number.isNaN(Date.parse(value));
}

function recordUnknownKeys(obj: Record<string, unknown>, allowed: ReadonlySet<string>, path: string, errors: string[]): void {
  for (const key of Object.keys(obj)) {
    if (!allowed.has(key)) errors.push(`${path}: unexpected field "${key}"`);
  }
}

function requireObject(value: unknown, path: string, errors: string[]): Record<string, unknown> | undefined {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    errors.push(`${path}: expected object`);
    return undefined;
  }
  return value as Record<string, unknown>;
}

function stampEventTimestamp(event: TraceV3Event, startTime: string): TraceV3Event {
  const origin = Date.parse(startTime);
  if (Number.isNaN(origin)) return event;
  return { ...event, timestamp: new Date(origin + event.tick * 3000).toISOString() };
}

/**
 * Capture a restaurant-arena-trace-v3 record from a running game.
 * Overlay callers import this helper directly.
 */
export function captureArenaTrace(game: ArenaTraceCaptureSource, options: TraceCaptureOptions): RestaurantArenaTraceV3 {
  const recorded = structuredClone(options.events ?? game.getRecordedEvents()) as TraceV3Event[];
  const additional = structuredClone(options.additionalEvents ?? []) as TraceV3Event[];
  for (const event of additional) {
    event.round = roundForTick(event.tick);
  }
  let events = [...recorded, ...additional];
  if (options.startTime) {
    events = events.map((event) => stampEventTimestamp(event, options.startTime!));
  }

  const state = game.state();
  const trace: RestaurantArenaTraceV3 = {
    version: TRACE_V3_VERSION,
    episodeId: options.episodeId ?? state.episode.id,
    seed: state.seed,
    envVersion: options.envVersion ?? ARENA_ENV_VERSION,
    contractVersion: TRACE_V3_CONTRACT_VERSION,
    runKind: options.runKind,
    initialState: game.getInitialState(),
    events,
    replay: game.getReplayRecord(),
    terminal: game.getTerminalStatus(),
    deletion: {
      requestId: options.deletion?.requestId !== undefined ? options.deletion.requestId : null,
      status: options.deletion?.status ?? "retained",
    },
  };
  if (options.sessionId !== undefined) trace.sessionId = options.sessionId;
  return trace;
}

/** Pretty-printed JSON export of a v3 trace. */
export function exportTraceJson(trace: RestaurantArenaTraceV3): string {
  return `${JSON.stringify(trace, null, 2)}\n`;
}

/**
 * JSONL export: one header line (trace without events) followed by one line per event.
 */
export function exportTraceJsonl(trace: RestaurantArenaTraceV3): string {
  const { events, ...header } = trace;
  return `${[JSON.stringify(header), ...events.map((event) => JSON.stringify(event))].join("\n")}\n`;
}

function validateModel(model: unknown, path: string, errors: string[]): void {
  const obj = requireObject(model, path, errors);
  if (!obj) return;
  recordUnknownKeys(obj, new Set(["provider", "name", "version"]), path, errors);
  if (typeof obj.provider !== "string" || obj.provider.length < 1) errors.push(`${path}.provider: expected non-empty string`);
  if (typeof obj.name !== "string" || obj.name.length < 1) errors.push(`${path}.name: expected non-empty string`);
  if (obj.version !== undefined && (typeof obj.version !== "string" || obj.version.length < 1)) {
    errors.push(`${path}.version: expected non-empty string`);
  }
}

function validateToolResult(result: unknown, path: string, errors: string[]): void {
  if (result === null) return;
  const obj = requireObject(result, path, errors);
  if (!obj) return;
  if (obj.ok !== undefined && typeof obj.ok !== "boolean") errors.push(`${path}.ok: expected boolean`);
  if (obj.latencyMs !== undefined && (typeof obj.latencyMs !== "number" || obj.latencyMs < 0)) {
    errors.push(`${path}.latencyMs: expected number >= 0`);
  }
  if (obj.queueMs !== undefined && typeof obj.queueMs !== "number") errors.push(`${path}.queueMs: expected number`);
  if (obj.providerMs !== undefined && typeof obj.providerMs !== "number") errors.push(`${path}.providerMs: expected number`);
  if (obj.roundMs !== undefined && typeof obj.roundMs !== "number") errors.push(`${path}.roundMs: expected number`);
  if (obj.inputTokens !== undefined && !isInteger(obj.inputTokens)) errors.push(`${path}.inputTokens: expected integer`);
  if (obj.outputTokens !== undefined && !isInteger(obj.outputTokens)) errors.push(`${path}.outputTokens: expected integer`);
  if (obj.cachedInputTokens !== undefined && !isInteger(obj.cachedInputTokens)) errors.push(`${path}.cachedInputTokens: expected integer`);
  if (obj.finishReason !== undefined && typeof obj.finishReason !== "string") errors.push(`${path}.finishReason: expected string`);
  const failed = obj.ok === false;
  const errorPresent = obj.error !== undefined && obj.error !== null;
  if (obj.error === undefined) {
    if (failed) errors.push(`${path}.error: required when ok is false`);
    return;
  }
  if (obj.error === null) {
    if (failed) errors.push(`${path}.error: required when ok is false`);
    return;
  }
  const err = requireObject(obj.error, `${path}.error`, errors);
  if (!err) return;
  if (typeof err.code !== "string" || err.code.length < 1) errors.push(`${path}.error.code: expected non-empty string`);
  if (typeof err.message !== "string" || err.message.length < 1) errors.push(`${path}.error.message: expected non-empty string`);
  if (err.retryable !== undefined && typeof err.retryable !== "boolean") errors.push(`${path}.error.retryable: expected boolean`);
  if (!failed && errorPresent) errors.push(`${path}.ok: must be false when error is present`);
}

function validateSubject(subject: unknown, path: string, errors: string[]): void {
  const obj = requireObject(subject, path, errors);
  if (!obj) return;
  recordUnknownKeys(obj, new Set(["kind", "id"]), path, errors);
  if (typeof obj.kind !== "string" || !SUBJECT_KINDS.has(obj.kind)) errors.push(`${path}.kind: invalid subject kind`);
  if (!isArenaId(obj.id)) errors.push(`${path}.id: expected arena id`);
}

function validateNullableObject(value: unknown, path: string, errors: string[]): void {
  if (value === null) return;
  if (typeof value !== "object" || Array.isArray(value)) errors.push(`${path}: expected object or null`);
}

function validateEvent(event: unknown, path: string, errors: string[]): void {
  const obj = requireObject(event, path, errors);
  if (!obj) return;
  recordUnknownKeys(obj, EVENT_KEYS, path, errors);
  if (!isInteger(obj.tick) || obj.tick < 0) errors.push(`${path}.tick: expected integer >= 0`);
  if (typeof obj.kind !== "string" || !TRACE_EVENT_KINDS.has(obj.kind)) errors.push(`${path}.kind: invalid event kind`);
  if (!isDateTime(obj.timestamp)) errors.push(`${path}.timestamp: expected date-time`);
  if (!isSha256(obj.stateHash)) errors.push(`${path}.stateHash: expected sha256 hash`);
  if (obj.round !== undefined && (!isInteger(obj.round) || obj.round < 1)) errors.push(`${path}.round: expected integer >= 1`);
  if (obj.actorId !== undefined && !isArenaId(obj.actorId)) errors.push(`${path}.actorId: expected arena id`);
  if (obj.role !== undefined && (typeof obj.role !== "string" || !TRACE_ROLES.has(obj.role))) errors.push(`${path}.role: invalid role`);
  if (obj.targetRole !== undefined && (typeof obj.targetRole !== "string" || !TRACE_ROLES.has(obj.targetRole))) {
    errors.push(`${path}.targetRole: invalid role`);
  }
  if (obj.checkpointId !== undefined && !isArenaId(obj.checkpointId)) errors.push(`${path}.checkpointId: expected arena id`);
  if (obj.model !== undefined) validateModel(obj.model, `${path}.model`, errors);
  if (obj.requestId !== undefined && !isArenaId(obj.requestId)) errors.push(`${path}.requestId: expected arena id`);
  if (obj.idempotencyKey !== undefined) {
    if (typeof obj.idempotencyKey !== "string" || obj.idempotencyKey.length > 130 || !IDEMPOTENCY_PATTERN.test(obj.idempotencyKey)) {
      errors.push(`${path}.idempotencyKey: invalid idempotency key`);
    }
  }
  if (obj.text !== undefined && obj.text !== null && typeof obj.text !== "string") errors.push(`${path}.text: expected string or null`);
  if (obj.observation !== undefined) validateNullableObject(obj.observation, `${path}.observation`, errors);
  if (obj.action !== undefined) validateNullableObject(obj.action, `${path}.action`, errors);
  if (obj.toolResult !== undefined) validateToolResult(obj.toolResult, `${path}.toolResult`, errors);
  if (obj.outcome !== undefined) validateNullableObject(obj.outcome, `${path}.outcome`, errors);
  if (obj.correctionRationale !== undefined && obj.correctionRationale !== null && typeof obj.correctionRationale !== "string") {
    errors.push(`${path}.correctionRationale: expected string or null`);
  }
  if (obj.correctionCategory !== undefined && !CORRECTION_CATEGORIES.has(obj.correctionCategory as string | null)) {
    errors.push(`${path}.correctionCategory: invalid category`);
  }
  if (obj.changedDecisionEventId !== undefined && obj.changedDecisionEventId !== null && !isArenaId(obj.changedDecisionEventId)) {
    errors.push(`${path}.changedDecisionEventId: expected arena id or null`);
  }
  if (obj.probeEventId !== undefined && obj.probeEventId !== null && !isArenaId(obj.probeEventId)) {
    errors.push(`${path}.probeEventId: expected arena id or null`);
  }
  if (obj.subject !== undefined) validateSubject(obj.subject, `${path}.subject`, errors);
  if (obj.payload !== undefined) validateNullableObject(obj.payload, `${path}.payload`, errors);
}

function validateEnvelope(envelope: unknown, path: string, errors: string[]): void {
  const obj = requireObject(envelope, path, errors);
  if (!obj) return;
  recordUnknownKeys(
    obj,
