/**
 * Capture a fresh benchmark restaurant-arena-trace-v3 and write (or check)
 * contracts/fixtures/restaurant-arena-trace-v3.json.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { RestaurantGame } from "../src/games/restaurant-arena/restaurant-game.js";
import { exportTraceJson } from "../src/games/restaurant-arena/trace.js";

const FIXTURE_RELATIVE = "contracts/fixtures/restaurant-arena-trace-v3.json";
const FIXTURE_PATH = resolve(import.meta.dir, "..", FIXTURE_RELATIVE);
const BENCHMARK_SEED = 218220;
const BENCHMARK_START = "2026-09-05T18:00:00.000Z";
const BENCHMARK_EPISODE_ID = "dinner-rush-benchmark-218220";

function sortValue(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sortValue);
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.keys(value as Record<string, unknown>)
        .sort()
        .map((key) => [key, sortValue((value as Record<string, unknown>)[key])]),
    );
  }
  return value;
}

function tracesMatch(left: unknown, right: unknown): boolean {
  return JSON.stringify(sortValue(left)) === JSON.stringify(sortValue(right));
}

function playBenchmarkShift(): RestaurantGame {
  const game = new RestaurantGame(BENCHMARK_SEED, "dinner-rush");
  game.step("sim_start");
  for (let tick = 0; tick < 10; tick++) game.step("tick");
  game.step("verify_substitution");
  for (let tick = 0; tick < 14; tick++) game.step("tick");
  return game;
}

function captureBenchmarkTrace() {
  return playBenchmarkShift().captureTrace({
    runKind: "benchmark",
    episodeId: BENCHMARK_EPISODE_ID,
    startTime: BENCHMARK_START,
  });
}

const check = process.argv.includes("--check");
const captured = captureBenchmarkTrace();

if (check) {
  const onDisk = JSON.parse(readFileSync(FIXTURE_PATH, "utf8"));
  if (!tracesMatch(captured, onDisk)) {
    console.error("Fixture differs from a freshly captured benchmark trace");
    process.exit(1);
  }
  console.log("Fixture is current");
} else {
  writeFileSync(FIXTURE_PATH, exportTraceJson(captured));
  console.log(`Wrote ${FIXTURE_RELATIVE}`);
}

#!/usr/bin/env bun
/**
 * Load a restaurant-arena-trace-v3 JSON or JSONL file, validate it, and
 * natively replay it.
 */

import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { replayArenaTrace } from "../src/games/restaurant-arena/replay.js";
import {
  validateArenaTraceV3,
  type RestaurantArenaTraceV3,
} from "../src/games/restaurant-arena/trace.js";

function loadTrace(path: string): RestaurantArenaTraceV3 {
  const text = readFileSync(path, "utf8");
  if (path.endsWith(".jsonl")) {
    const lines = text.split(/\r?\n/).filter((line) => line.trim().length > 0);
    if (lines.length === 0) throw new Error("empty JSONL trace");
    const header = JSON.parse(lines[0]!);
    const events = lines.slice(1).map((line) => JSON.parse(line));
    return { ...header, events } as RestaurantArenaTraceV3;
  }
  return JSON.parse(text) as RestaurantArenaTraceV3;
}

const fileArg = process.argv[2];
if (!fileArg) {
  console.error("Usage: bun scripts/replay-arena-trace.ts <path-to-trace.json-or-.jsonl>");
  process.exit(1);
}

try {
  const trace = loadTrace(resolve(fileArg));
  const validation = validateArenaTraceV3(trace);
  if (!validation.valid) {
    console.error(validation.errors.join("\n"));
    process.exit(1);
  }
  replayArenaTrace(trace);
  console.log("Native replay passed");
} catch (error) {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
}

