    if (record.id === "worker-expediter" || record.id === "expediter") record.id = "worker-supply_lead";
  }
  return copy;
}

export function applyArenaReplayInput(game: RestaurantGame, input: ArenaInputRecord, _index = 0): void {
  switch (input.kind) {
    case "step":
      game.step(input.action);
      return;
    case "time":
      game.advanceTime();
      return;
    case "envelope":
      game.stepEnvelope(input.envelope, input.telemetry);
      return;
    case "controllers":
      game.setExternalControllers(input.roles);
      return;
  }
}

/**
 * Rebuild a live RestaurantGame from a captured v3 trace.
 * Throws if the engine's own tick-0 state, any checkpoint hash, or the
 * terminal record disagrees with what native replay produces.
 */
export function replayArenaTrace(trace: RestaurantArenaTraceV3): RestaurantGame {
  const game = new RestaurantGame(trace.seed, trace.replay.variation);
  const engineInitial = canonicalizeLegacyRoster(game.getInitialState());
  const recordedInitial = canonicalizeLegacyRoster(trace.initialState);
  if (computeStateHash(engineInitial) !== computeStateHash(recordedInitial)) {
    throw new Error("initial state hash mismatch");
  }

  for (const [index, input] of trace.replay.inputs.entries()) {
    applyArenaReplayInput(game, input, index);
    const checkpointHash = computeStateHash(game.checkpointState());
    if (checkpointHash !== input.stateHash) {
      throw new Error(`checkpoint mismatch at input ${index}`);
    }
    if (input.restaurantStateHash !== undefined && input.restaurantStateHash !== computeStateHash(game.state())) {
      throw new Error(`restaurant state hash mismatch at input ${index}`);
    }
  }

  if (computeStateHash(game.checkpointState()) !== trace.replay.finalStateHash) {
    throw new Error("final state hash mismatch");
  }
  if (
    trace.replay.finalRestaurantStateHash !== undefined &&
    trace.replay.finalRestaurantStateHash !== computeStateHash(game.state())
  ) {
    throw new Error("final restaurant state hash mismatch");
  }

  if (JSON.stringify(game.getTerminalStatus()) !== JSON.stringify(trace.terminal)) {
    throw new Error("terminal mismatch");
  }

  return game;
}
