import { describe, expect, it } from "bun:test";
import { RestaurantGame } from "./restaurant-game.js";
import { replayArenaTrace } from "./replay.js";
import {
  captureArenaTrace,
  exportTraceJson,
  exportTraceJsonl,
  validateArenaTraceV3,
  type RestaurantArenaTraceV3,
  type TraceV3Event,
} from "./trace.js";

function playShortShift(seed = 218220): RestaurantGame {
  const game = new RestaurantGame(seed, "dinner-rush");
  game.step("sim_start");
  for (let i = 0; i < 4; i++) game.step("tick");
  return game;
}

function validHash(event: TraceV3Event): string {
  return event.stateHash;
}

describe("restaurant-arena-trace-v3 capture / export / validate", () => {
  it("captures a schema-valid record from a running game", () => {
    const game = playShortShift();
    const viaHelper = captureArenaTrace(game, { runKind: "live" });
    const viaMethod = game.captureTrace({ runKind: "live" });

    expect(viaMethod).toEqual(viaHelper);
    expect(viaHelper.version).toBe("restaurant-arena-trace/v3");
    expect(viaHelper.runKind).toBe("live");
    expect(viaHelper.contractVersion).toBe("restaurant-arena/v1");
    expect(viaHelper.initialState).toEqual(game.getInitialState());
    expect(viaHelper.events.length).toBeGreaterThan(0);
    expect(viaHelper.terminal).toEqual(game.getTerminalStatus());
    expect(viaHelper.replay.inputs.length).toBeGreaterThan(0);
    expect(viaHelper.deletion).toEqual({ requestId: null, status: "retained" });

    const validation = validateArenaTraceV3(viaHelper);
    expect(validation.valid).toBe(true);
    expect(validation.errors).toEqual([]);
  });

  it("stamps additionalEvents with the round their tick falls in", () => {
    const game = playShortShift();
    const extra: TraceV3Event = {
      tick: 4,
      kind: "message",
      timestamp: "2026-09-05T18:00:12.000Z",
      stateHash: game.getRecordedEvents()[0]!.stateHash,
      actorId: "player",
      text: "out-of-band note",
    };
    const trace = game.captureTrace({ runKind: "synthetic", additionalEvents: [extra] });
    const found = trace.events.find((event) => event.text === "out-of-band note");
    expect(found).toBeDefined();
    expect(found!.round).toBe(2);
    expect(trace.runKind).toBe("synthetic");
  });

  it("rewrites event timestamps from startTime and honors episodeId", () => {
    const game = playShortShift();
    const trace = captureArenaTrace(game, {
      runKind: "benchmark",
      episodeId: "dinner-rush-benchmark-218220",
      startTime: "2026-09-05T18:00:00.000Z",
    });
    expect(trace.episodeId).toBe("dinner-rush-benchmark-218220");
    for (const event of trace.events) {
      expect(event.timestamp).toBe(new Date(Date.parse("2026-09-05T18:00:00.000Z") + event.tick * 3000).toISOString());
    }
  });

  it("exports JSON and JSONL that round-trip through the validator", () => {
    const game = playShortShift();
    const trace = captureArenaTrace(game, { runKind: "live" });
    const parsed = JSON.parse(exportTraceJson(trace));
    expect(validateArenaTraceV3(parsed).valid).toBe(true);

    const jsonl = exportTraceJsonl(trace);
    const lines = jsonl.trim().split("\n");
    expect(lines.length).toBe(trace.events.length + 1);
    expect(JSON.parse(lines[0]!)).toMatchObject({ version: trace.version, replay: trace.replay });
    const rebuilt = { ...JSON.parse(lines[0]!), events: lines.slice(1).map((line) => JSON.parse(line)) };
    expect(validateArenaTraceV3(rebuilt).valid).toBe(true);
  });

  it("rejects malformed records field by field", () => {
    const game = playShortShift();
    const trace = captureArenaTrace(game, { runKind: "live" });

    const badSeed = validateArenaTraceV3({ ...trace, seed: "nope" });
    expect(badSeed.valid).toBe(false);
    expect(badSeed.errors.some((error) => error.includes("seed"))).toBe(true);

    const badKind = validateArenaTraceV3({ ...trace, runKind: "demo" });
    expect(badKind.valid).toBe(false);
    expect(badKind.errors.some((error) => error.includes("runKind"))).toBe(true);

    const extraField = validateArenaTraceV3({ ...trace, extra: true });
    expect(extraField.valid).toBe(false);
    expect(extraField.errors.some((error) => error.includes("extra"))).toBe(true);

    const badReason = validateArenaTraceV3({
      ...trace,
      terminal: { ...trace.terminal, reason: 12 },
    });
    expect(badReason.valid).toBe(false);
    expect(badReason.errors.some((error) => error.includes("reason"))).toBe(true);

    const badCash = structuredClone(trace) as RestaurantArenaTraceV3;
    (badCash.initialState as { outcomes: { cash: unknown } }).outcomes.cash = "free";
    const cashResult = validateArenaTraceV3(badCash);
    expect(cashResult.valid).toBe(false);
    expect(cashResult.errors.some((error) => error.includes("cash"))).toBe(true);
  });
});

describe("identifying the session a trace came from (#281)", () => {
  it("records an optional sessionId when the caller supplies one", () => {
    const game = playShortShift();
    const trace = captureArenaTrace(game, { runKind: "live", sessionId: "game_abc-123" });
    expect(trace.sessionId).toBe("game_abc-123");
    expect(validateArenaTraceV3(trace).valid).toBe(true);
  });

  it("keeps two runs of one scenario distinguishable", () => {
    const first = playShortShift().captureTrace({ runKind: "live", sessionId: "session-one" });
    const second = playShortShift().captureTrace({ runKind: "live", sessionId: "session-two" });
    expect(first.episodeId).toBe(second.episodeId);
    expect(first.sessionId).not.toBe(second.sessionId);
  });

  it("treats a missing sessionId as valid", () => {
    const trace = playShortShift().captureTrace({ runKind: "live" });
    expect(trace.sessionId).toBeUndefined();
    expect(validateArenaTraceV3(trace).valid).toBe(true);
  });

  it("rejects a malformed sessionId", () => {
    const trace = playShortShift().captureTrace({ runKind: "live", sessionId: "not a valid id" });
    const result = validateArenaTraceV3(trace);
    expect(result.valid).toBe(false);
    expect(result.errors.some((error) => error.includes("sessionId"))).toBe(true);
  });
});

describe("native replayArenaTrace", () => {
  it("rebuilds the live game and matches terminal status", () => {
    const game = playShortShift();
    const trace = game.captureTrace({ runKind: "live" });
    const replayed = replayArenaTrace(trace);
    expect(replayed).toBeInstanceOf(RestaurantGame);
    expect(replayed.getTerminalStatus()).toEqual(trace.terminal);
    expect(replayed.state().episode.tick).toBe(game.state().episode.tick);
  });

  it("rejects an initialState that has been altered in any field", () => {
    const trace = playShortShift().captureTrace({ runKind: "live" });
    const tampered = structuredClone(trace);
    (tampered.initialState as { outcomes: { cash: number } }).outcomes.cash = 99;
    expect(() => replayArenaTrace(tampered)).toThrow(/initial state hash mismatch/);
  });

  it("tolerates the legacy expediter roster in initialState", () => {
    const trace = playShortShift().captureTrace({ runKind: "live" });
    const legacy = structuredClone(trace);
    const workers = (legacy.initialState as { workers: Array<{ id: string; role: string }> }).workers;
    for (const worker of workers) {
      if (worker.role === "supply_lead") {
        worker.role = "expediter";
        worker.id = "worker-expediter";
      }
    }
    expect(replayArenaTrace(legacy).getTerminalStatus()).toEqual(trace.terminal);
  });

  it("throws when any part of the recorded terminal disagrees", () => {
    const trace = playShortShift().captureTrace({ runKind: "live" });
    const badReason = { ...trace, terminal: { ...trace.terminal, reason: "tampered" } };
    expect(() => replayArenaTrace(badReason)).toThrow(/terminal mismatch/);

    const badTick = { ...trace, terminal: { ...trace.terminal, tick: trace.terminal.tick + 1 } };
    expect(() => replayArenaTrace(badTick)).toThrow(/terminal mismatch/);
  });

  it("throws when a checkpoint hash disagrees", () => {
    const trace = playShortShift().captureTrace({ runKind: "live" });
    const tampered = structuredClone(trace);
    tampered.replay.inputs[0]!.stateHash = "sha256:" + "0".repeat(64);
    expect(() => replayArenaTrace(tampered)).toThrow(/checkpoint mismatch/);
  });
});

void validHash;

