// In RestaurantGame.ts
captureTrace(options: TraceCaptureOptions): RestaurantArenaTraceV3 {
  const { runKind, additionalEvents = [] } = options;
  if (!['live', 'synthetic', 'benchmark'].includes(runKind)) {
    throw new Error(`Invalid runKind ${runKind}`);
  }
  const events: TraceV3Event[] = [];
  // Capture tick-0 state
  const initialState = this.getInitialState();
  events.push({
    kind: 'tick',
    tick: 0,
    state: initialState,
    inputs: [],
    status: 0,
    reason: null
  });
  // Capture event history
  for (const event of this.journal) {
    events.push(event);
  }
  // Add additional events
  for (const event of additionalEvents) {
    events.push(event);
  }
  // Build trace
  const trace = {
    version: TRACE_V3_VERSION,
    episodeId: this.episodeId,
    runKind,
    events,
    terminal: {
      status: this.status,
      tick: this.tick,
      reason: this.reason
    }
  };
  return trace;
}
